// v16.xx (partyp5), from the cloud review of 2026-10-15 (item 9), and his order that the magnet pull loose loot to the picker and never containers. The magnet used
// to slide wrecks, bodies and the stronghold cache toward the player. The stronghold cache (made at the start of the raid) and the convoy crate slid out through
// a shut fence to anyone standing at it, and in co-op each window moved its own copy of a box: the host then answered a search of player 2's box with FAR
// for a box that was at his feet on his screen, and the host's own magnet pulled boxes that never moved on player 2's. A container is never moved now. The magnet
// pulls the loose loot on the floor to the player (the pickups, as before, from the same reach), the same in both windows because a pickup belongs to its window.
function pwrMagnet(p,dt,S){

check:
{v:'VER',what:'partyp5, from the cloud review (9): the magnet pulls the pickups on the floor to the player and never moves a container (a body, a wreck, the stronghold cache or the convoy crate), so nothing slides through a fence and co-op boxes stay where both windows have them',
 run:function(){
   if(!(window.__state&&window.__endRaid&&window.__runPrep&&window.__sim)) return 'SKIP: no raid here';
   if(typeof arcadeDeploy!=='function'||typeof ARCADE!=='object'||typeof pwrMagnet!=='function') return 'SKIP: no arcade here';
   var bad=[], g=null, p, own=false, rs=say, S, i, j, a, x, y, ok, bo, wr, ca, cx0, d0, d1, pk;
   function step(n){ var k; for(k=0;k<n;k++){ g.t+=0.016; __sim(0.016); } }
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     if(ARCADE.on) return 'SKIP: the arcade is on after __topClear';
     if(!arcadeDeploy({mapIx:0,seed:4242})) return 'SKIP: arcadeDeploy built no arcade raid';
     g=__state(); if(!g||g.over||!g.player) return 'SKIP: no live raid';
     p=g.player; keys={}; say=function(){}; own=true; ARCADE.holdT=0;
     g.ents=g.ents.filter(function(q2){ return q2&&(q2.neutral||q2.kind==='peddler'||q2.kind==='stray'); });
     g.pwr=null; S=pwrS(); S.items.length=0; S.act={}; ok=0;
     for(j=0;j<12&&!ok;j++){
       a=j*0.5236; x=p.x+Math.cos(a)*300; y=p.y+Math.sin(a)*300;
       if(losClear(p.x,p.y,x,y,g.map.segs)&&!shutRoomAt(g.map,x,y)){ ok=1; for(i=0;i<=20;i++) if(!spotFree(g.map,p.x+(x-p.x)*i/20,p.y+(y-p.y)*i/20,16)) ok=0; }
     }
     if(!ok) return 'SKIP: staging: no open ground 300 from the drop for test boxes';
     bo=setLoot(mkContainer(x,y,'body'),['scrap']); wr=setLoot(mkContainer(x+14,y+10,'botwreck'),['scrap']); ca=setLoot(mkContainer(x-14,y-10,'cache'),['scrap']); ca.tag='STRONGHOLD '+'CACHE'; ca.wreck=1;
     g.containers.push(bo,wr,ca); g.searching=null;
     cx0=[[bo.x,bo.y],[wr.x,wr.y],[ca.x,ca.y]];
     // ONE: with the magnet running no container moves, a body, a wreck or the cache
     S.act.mag=20; step(200);
     [bo,wr,ca].forEach(function(c,k){ if(Math.hypot(c.x-cx0[k][0],c.y-cx0[k][1])>0.5) bad.push('ONE: the magnet moved a '+['body','wreck','cache'][k]+' '+Math.round(Math.hypot(c.x-cx0[k][0],c.y-cx0[k][1]))+' units'); });
     // TWO: a pickup on the floor still comes to the player
     S.items.length=0; S.items.push({k:'dmg',x:p.x+400,y:p.y,t:0,life:16,id:1}); pk=S.items[0]; d0=Math.hypot(p.x-pk.x,p.y-pk.y); step(60);
     d1=S.items.length?Math.hypot(p.x-S.items[0].x,p.y-S.items[0].y):0;
     if(S.items.length&&!(d0-d1>=100)) bad.push('TWO: a pickup 400 away came only '+Math.round(d0-d1)+' closer under the magnet');
   }catch(x2){ bad.push('threw: '+(x2&&x2.message||x2)); }
   finally{
     if(own) say=rs;
     keys={};
     try{ if(g){ g.pwr=null; g.bullets.length=0; g.searching=null; } }catch(_gp){}
     try{ if(typeof ARCADE==='object'&&ARCADE.on) arcadeLeave(); }catch(_l){}
     try{ if(__state()&&!__state().over) __endRaid('abandon'); }catch(_e){}
     try{ if(typeof ARCADE==='object'){ ARCADE.mine=0; ARCADE.waveT=0; ARCADE.holdT=0; ARCADE.streak=null; } }catch(_h){}
     __topClear();
   }
   return bad.length?bad.slice(0,8).join('; '):null; }},
